import React, { useEffect, useState, useCallback, useRef } from 'react';
import { useLang } from '../LangContext';

const TOTAL = 15; // 3 × 5s

export default function AdSplash({ onDone }) {
  const { t } = useLang();
  const [banners, setBanners] = useState(null);
  const [index, setIndex]     = useState(0);
  const [elapsed, setElapsed] = useState(0);
  const [imgLoaded, setImgLoaded] = useState(false);
  const slotRef = useRef(null);

  const fetchBanners = useCallback(() => {
    fetch('http://localhost:5000/api/banners/current')
      .then(r => r.json())
      .then(data => {
        if (!data.banners?.length) { onDone(); return; }
        setBanners(data.banners);
        setIndex(0); setElapsed(0); setImgLoaded(false);
        if (slotRef.current) clearTimeout(slotRef.current);
        if (data.slot_ends_in_ms > 0)
          slotRef.current = setTimeout(fetchBanners, data.slot_ends_in_ms);
      })
      .catch(onDone);
  }, [onDone]);

  useEffect(() => { fetchBanners(); return () => clearTimeout(slotRef.current); }, [fetchBanners]);

  useEffect(() => {
    if (!banners) return;
    const tick = setInterval(() => {
      setElapsed(prev => {
        const next = prev + 1;
        if (next >= TOTAL) { clearInterval(tick); onDone(); return TOTAL; }
        const ni = Math.floor(next / 5);
        setIndex(cur => { if (ni !== cur) setImgLoaded(false); return ni < banners.length ? ni : cur; });
        return next;
      });
    }, 1000);
    return () => clearInterval(tick);
  }, [banners, onDone]);

  if (!banners) return (
    <div style={s.overlay}>
      <div style={s.spinner} />
    </div>
  );

  const banner    = banners[index];
  const secLeft   = TOTAL - elapsed;
  const secInBanner = elapsed % 5;
  const totalPct  = (elapsed / TOTAL) * 100;

  return (
    <div style={s.overlay}>
      {/* Full-screen image */}
      {banner?.url && (
        <img key={banner.url} src={banner.url} alt=""
          onLoad={() => setImgLoaded(true)}
          style={{ ...s.bgImg, opacity: imgLoaded ? 1 : 0 }} />
      )}
      {!imgLoaded && <div style={s.shimmer} />}

      {/* Gradients */}
      <div style={s.gradTop} />
      <div style={s.gradBottom} />

      {/* ── HEADER: logo | minus-dots | small countdown ── */}
      <div style={s.header}>
        <span style={s.logo}>All <span style={{ color: '#f97316' }}>Things</span></span>

        {/* Minus/dash segment indicators */}
        <div style={s.dots}>
          {banners.map((_, i) => {
            const done    = i < index;
            const current = i === index;
            const fill    = done ? '100%' : current ? `${(secInBanner / 5) * 100}%` : '0%';
            return (
              <div key={i} style={s.dotTrack}>
                <div style={{
                  height: '100%', width: fill, borderRadius: 2,
                  background: done ? '#22c55e' : '#f97316',
                  transition: current ? 'width 1s linear' : 'none',
                }} />
              </div>
            );
          })}
        </div>

        {/* Small countdown in header */}
        <div style={s.headerTimer}>
          <span style={s.timerNum}>{secLeft}</span>
          <span style={s.timerLabel}>s</span>
        </div>
      </div>

      {/* ── BOTTOM: ad label + watch message + overall bar ── */}
      <div style={s.bottom} className="ad-bottom">
        <div style={s.badge}>📢 {t.adOf(index + 1, banners.length)}</div>

        <p style={s.watchMsg} className="ad-title">{t.watchAd}</p>
        <p style={s.subMsg}>{t.secondsLeft(secLeft)}</p>

        {/* Overall progress bar */}
        <div style={s.track}>
          <div style={{ ...s.fill, width: `${totalPct.toFixed(1)}%`, transition: 'width 1s linear' }} />
        </div>
        <p style={s.trackLabel}>{t.overall}: {Math.round(totalPct)}% {t.complete}</p>
      </div>
    </div>
  );
}

const s = {
  overlay: { position: 'fixed', inset: 0, zIndex: 9999, background: '#000', overflow: 'hidden', userSelect: 'none' },
  bgImg: { position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover', transition: 'opacity 0.4s' },
  shimmer: { position: 'absolute', inset: 0, background: 'linear-gradient(110deg,#111 30%,#1c1c1c 50%,#111 70%)', backgroundSize: '200% 100%', animation: 'shimmer 1.4s infinite' },
  gradTop: { position: 'absolute', top: 0, left: 0, right: 0, height: 100, background: 'linear-gradient(to bottom,rgba(0,0,0,0.9),transparent)', pointerEvents: 'none' },
  gradBottom: { position: 'absolute', bottom: 0, left: 0, right: 0, height: 220, background: 'linear-gradient(to top,rgba(0,0,0,0.92),transparent)', pointerEvents: 'none' },

  // Header
  header: { position: 'absolute', top: 0, left: 0, right: 0, padding: '14px 20px', display: 'flex', alignItems: 'center', gap: 12 },
  logo: { fontSize: 18, fontWeight: 900, color: '#fff', flexShrink: 0 },
  dots: { flex: 1, display: 'flex', gap: 6, alignItems: 'center' },
  dotTrack: { flex: 1, height: 4, background: 'rgba(255,255,255,0.2)', borderRadius: 2, overflow: 'hidden', maxWidth: 80 },
  headerTimer: { display: 'flex', alignItems: 'baseline', gap: 1, flexShrink: 0 },
  timerNum: { fontSize: 18, fontWeight: 900, color: '#f97316', lineHeight: 1 },
  timerLabel: { fontSize: 11, color: 'rgba(255,255,255,0.5)' },

  // Bottom
  bottom: { position: 'absolute', bottom: 0, left: 0, right: 0 },
  badge: { display: 'inline-block', background: 'rgba(249,115,22,0.18)', border: '1px solid rgba(249,115,22,0.4)', color: '#f97316', fontSize: 11, fontWeight: 700, padding: '4px 12px', borderRadius: 20, marginBottom: 10, letterSpacing: 0.5 },
  watchMsg: { color: '#fff', fontSize: 20, fontWeight: 800, marginBottom: 4, textShadow: '0 2px 8px rgba(0,0,0,0.8)', lineHeight: 1.2 },
  subMsg: { color: 'rgba(255,255,255,0.5)', fontSize: 13, marginBottom: 14 },
  track: { height: 4, background: 'rgba(255,255,255,0.15)', borderRadius: 2, overflow: 'hidden' },
  fill: { height: '100%', background: '#f97316', borderRadius: 2 },
  trackLabel: { color: 'rgba(255,255,255,0.35)', fontSize: 11, marginTop: 5 },
  spinner: { position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%,-50%)', width: 36, height: 36, border: '3px solid rgba(249,115,22,0.3)', borderTopColor: '#f97316', borderRadius: '50%', animation: 'spin 0.8s linear infinite' },
};
